import { uv, mix, smoothstep, vec3, step } from 'three/tsl';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, DoubleSide } = THREE;

  const root = new Group();
  root.userData.handlers = {};
  const timelines = [];

  const width = 2.6;
  const height = 0.68;

  // Main button group
  const btnGroup = new Group();
  root.add(btnGroup);

  // Face plane with engineered gradient
  const faceGeom = new PlaneGeometry(width, height, 32, 8);

  // TSL gradient construction
  const uvNode = uv();

  // Define colors in 0-1 RGB range
  const colorTop = vec3(1.0, 0.267, 0.314);    // #ff4450
  const colorMid = vec3(1.0, 0.165, 0.224);    // #ff2a38
  const colorBtm = vec3(0.757, 0.071, 0.122);  // #c1121f

  // Hard seam at y=0.5 using step function
  const seamMask = step(vec3(0.5), uvNode.yyy);

  // Gradient below seam (0.0 → 0.55): colorTop → colorMid
  const gradBelow = mix(colorTop, colorMid, smoothstep(vec3(0.0), vec3(0.55), uvNode.yyy));

  // Gradient above seam (0.55 → 1.0): colorMid → colorBtm
  const gradAbove = mix(colorMid, colorBtm, smoothstep(vec3(0.55), vec3(1.0), uvNode.yyy));

  // Combine with hard transition at seam
  const gradientColor = mix(gradBelow, gradAbove, seamMask);

  // Material with PBR properties
  const faceMat = new MeshStandardNodeMaterial({
    roughness: 0.5,
    metalness: 0.35,
    clearcoat: 0.22,
    side: DoubleSide,
  });

  faceMat.colorNode = gradientColor;
  faceMat.emissiveNode = vec3(1.0, 0.165, 0.224); // #ff2a38
  faceMat.emissiveIntensity = 1.6;

  const faceMesh = new Mesh(faceGeom, faceMat);
  btnGroup.add(faceMesh);

  // Label text
  const labelText = ctx.fontAtlas.createText('BEGIN COMMISSION', {
    fontSize: 20,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 1.6, // 0.08em × 20px
  });
  labelText.position.z = 0.015;
  btnGroup.add(labelText);

  // Caption text
  const captionText = ctx.fontAtlas.createText('NO DEPOSIT REQUIRED', {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 1.08, // 0.12em × 9px
  });
  captionText.position.y = -(height / 2 + 0.25);
  captionText.position.z = 0;
  btnGroup.add(captionText);

  // Contact shadow plane
  const shadowGeom = new PlaneGeometry(width * 1.1, height * 1.1);
  const shadowMat = new MeshBasicNodeMaterial({
    color: '#000000',
    transparent: true,
    opacity: 0.35,
  });
  const shadowMesh = new Mesh(shadowGeom, shadowMat);
  shadowMesh.position.z = -0.08;
  root.add(shadowMesh);

  // Mount animation: weighted-settle scale 1.04 → 1.0 over 900ms
  const mountTL = gsap.timeline();
  mountTL.fromTo(
    root.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' }
  );
  timelines.push(mountTL);

  // Hover state: translateZ 0 → 0.06, emissive 1.6 → 2.2
  let hoverInTL = null, hoverOutTL = null;
  root.userData.handlers.hover = {
    enter: () => {
      if (hoverOutTL) hoverOutTL.kill();
      hoverInTL = gsap.timeline();
      hoverInTL.to(faceMesh.position, { z: 0.06, duration: 0.18 }, 0);
      hoverInTL.to(faceMat, { emissiveIntensity: 2.2 }, 0);
      hoverInTL.to(shadowMesh.scale, { x: 0.95, y: 0.95, duration: 0.18 }, 0);
      timelines.push(hoverInTL);
    },
    leave: () => {
      if (hoverInTL) hoverInTL.kill();
      hoverOutTL = gsap.timeline();
      hoverOutTL.to(faceMesh.position, { z: 0, duration: 0.18 }, 0);
      hoverOutTL.to(faceMat, { emissiveIntensity: 1.6 }, 0);
      hoverOutTL.to(shadowMesh.scale, { x: 1.1, y: 1.1, duration: 0.18 }, 0);
      timelines.push(hoverOutTL);
    }
  };

  // Press state: scale 1.0 → 0.97 over 120ms, shadow tightens
  let pressTL = null, releaseTL = null;
  root.userData.handlers.press = {
    down: () => {
      if (releaseTL) releaseTL.kill();
      pressTL = gsap.timeline();
      pressTL.to(root.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' }, 0);
      pressTL.to(shadowMesh.scale, { x: 0.85, y: 0.85, duration: 0.12 }, 0);
      timelines.push(pressTL);
    },
    up: () => {
      if (pressTL) pressTL.kill();
      releaseTL = gsap.timeline();
      releaseTL.to(root.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.12 }, 0);
      releaseTL.to(shadowMesh.scale, { x: 1.1, y: 1.1, duration: 0.12 }, 0);
      timelines.push(releaseTL);
    }
  };

  // Cleanup
  root.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    faceGeom.dispose();
    faceMat.dispose();
    shadowGeom.dispose();
    shadowMat.dispose();
  };

  return root;
}
